"""Vendored copy of the canonical ISC grammar:

    interscript-ruby lib/interscript/isc/grammar/isc.parg

The .parg file is the single semantic source of the ISC syntax; this
module embeds it verbatim (sha256 52949cb3170554071c8085bc5388553fde3d9a7feb590109d4543478d3561bb7) so the Python parser compiles
the same grammar text the Ruby runtime ships. Update procedure:

    python scripts/sync_isc_grammar.py <path-to-interscript-ruby>

The sync script rewrites this file and the sha256 pin; the pin test
(tests/test_grammar_source.py) fails when the embedded text and the
recorded hash disagree, so drift is never silent.

This is the same file (same sha256 pin) that interscript-ts vendors via
its scripts/sync-isc-grammar.mjs — the two generated parsers must never
compile different grammar texts.
"""

from __future__ import annotations

# sha256 of the grammar text embedded below (pin for drift detection).
ISC_PARG_SHA256 = "52949cb3170554071c8085bc5388553fde3d9a7feb590109d4543478d3561bb7"

# The grammar text itself, byte-identical to the ruby checkout copy.
ISC_PARG_SOURCE = "# Interscript ISC grammar \u2014 parsanol grammar language (PG).\n#\n# Line-oriented port of lib/interscript/isc/grammar/concerns/*.rb.\n# The capture tree must reproduce the Ruby-DSL parser's tree exactly:\n#   - repetitions are ABNF prefixes (1*x, *x)\n#   - negation is !x, positive lookahead is &x\n#   - captures at use sites (rule_ref as name) nest inner captures\n#     the same way parslet .as does\n#\n# Consumed by the interscript gem (artifact parse) and parsanol npm.\n\ngrammar InterscriptIsc version \"0.1.0\" {\n\n  # -- lexical primitives -------------------------------------------------\n\n  chr = %x00-10FFFF\n  space_char = %x20 / %x09 / %x0A / %x0B / %x0C / %x0D\n  newline = %x0D.0A / %x0A / %x0D\n  line_comment = \"#\" *(!(newline) chr)\n  whitespace = 1*(space_char / line_comment)\n  ws = *(space_char / line_comment)\n  inline_space = 1*(%x20 / %x09)\n  inline_ws = *(inline_space / line_comment)\n  hexd = %x30-39 / %x41-46 / %x61-66\n  digit = %x30-39\n\n  ident_first = %x41-5A / %x61-7A / %x5F\n  ident_rest = %x41-5A / %x61-7A / %x30-39 / %x5F\n  identifier = (ident_first 0*ident_rest) as identifier\n\n  keyword = \"parallel\" / \"sequence\" / \"stage\" / \"compose\" / \"separate\" / \"system\" / \"metadata\" / \"aliases\" / \"tests\" / \"notes\" / \"description\" / \"any_character\" / \"authority\" / \"dependency\" / \"run\" / \"sub\" / \"before\" / \"after\" / \"not_before\" / \"not_after\" / \"any\" / \"none\" / \"boundary\" / \"line_start\" / \"line_end\" / \"word_boundary\" / \"downcase\" / \"upcase\" / \"title_case\" / \"capture\" / \"maybe\" / \"some\" / \"ref\" / \"name\" / \"ruleset\" / \"use\" / \"override\" / \"languages\" / \"when\"\n\n  # -- string literals ----------------------------------------------------\n\n  esc_nl = (\"n\") as newline\n  esc_cr = (\"r\") as carriage_return\n  esc_tab = (\"t\") as tab\n  esc_dq = \"\\\"\" as dquote\n  esc_bs = \"\\\\\" as backslash\n  esc_uni4 = \"u\" (4hexd) as unicode\n  esc_uni8 = \"U\" (4*8hexd) as unicode\n  esc_u_lone = \"U\" as u_lone\n  escape_sequence = \"\\\\\" (esc_nl / esc_cr / esc_tab / esc_dq / esc_bs / esc_uni4 / esc_uni8 / esc_u_lone)\n\n  raw_run = 1*(!(\"\\\\\" / \"\\\"\") chr)\n  dq_parts = *(escape_sequence / (raw_run as run))\n  double_quoted = \"\\\"\" (dq_parts as string) \"\\\"\"\n  sq_body = *(!\"'\" chr)\n  single_quoted = \"'\" (sq_body as string) \"'\"\n  quoted_string = double_quoted / single_quoted\n\n  arrow = [whitespace] \"->\" [whitespace]\n  comma_ws = \",\" [whitespace]\n\n  # -- metadata -----------------------------------------------------------\n\n  md_authority = \"authority\" whitespace ((quoted_string) as authority)\n  md_source_spelling = \"source_spelling\" whitespace ((quoted_string) as source_spelling)\n  md_target_spelling = \"target_spelling\" whitespace ((quoted_string) as target_spelling)\n  md_identifying = \"identifying\" whitespace ((quoted_string) as identifying)\n  md_name = \"name\" whitespace ((quoted_string) as name)\n  md_spec_value = quoted_string as specification\n  md_specification = \"specification\" whitespace ((md_spec_value *(comma_ws md_spec_value)) as specification)\n  md_description = \"description\" [whitespace] \"{\" [ws] (raw_text as description) [ws] \"}\"\n  md_system_status = \"system_status\" whitespace ((\"current\" / \"former\" / \"inactive\") as system_status)\n  md_code_status = \"code_status\" whitespace ((\"preferred\" / \"proposed\" / \"deprecated\") as code_status)\n\n  relation_type = \"supersedes\" / \"superseded_by\" / \"based_on\" / \"basis_for\" / \"alias_of\" / \"adopted_from\" / \"related_to\"\n  relation_note = whitespace \"note\" whitespace (quoted_string as note)\n  relation_item = [whitespace] (relation_type as type) whitespace (quoted_string as system) [(relation_note)] [whitespace]\n  md_relations = \"relations\" [whitespace] \"{\" [ws] ((*(relation_item)) as relations) [ws] \"}\"\n\n  note_item = [whitespace] \"note\" [whitespace] (quoted_string as note) [whitespace]\n  md_notes = \"notes\" [whitespace] \"{\" [ws] ((*(note_item)) as notes) [ws] \"}\"\n\n  md_provenance_value = quoted_string as provenance\n  md_provenance = \"provenance\" [whitespace] ((md_provenance_value *(comma_ws md_provenance_value)) as provenance)\n\n  md_empty_field = &(newline)\n  md_raw_field_value = 1*(!%x0A !\"}\" !\"{\" chr)\n  md_field_value = quoted_string / (md_raw_field_value as raw)\n  md_field_block = \"{\" [ws] (raw_text as field_block) [ws] \"}\"\n  md_generic_field = (identifier as field_name) inline_ws ((md_field_value as field_value) / md_field_block / md_empty_field)\n\n  metadata_field = [whitespace] (md_description / md_relations / md_system_status / md_code_status / md_specification / md_notes / md_provenance / md_generic_field) [whitespace]\n  md_items = *(metadata_field)\n  metadata_block = \"metadata\" [whitespace] \"{\" [ws] (md_items as metadata) [ws] \"}\"\n\n  raw_text = *(\"\\\\\" chr / (!\"}\" chr))\n\n  # -- aliases ------------------------------------------------------------\n\n  alias_decl = [whitespace] (identifier as name) [whitespace] \"=\" [whitespace] (item as value) [whitespace]\n  alias_items = *(alias_decl)\n  aliases_block = \"aliases\" [whitespace] \"{\" [ws] (alias_items as aliases) [ws] \"}\"\n\n  # -- dependencies -------------------------------------------------------\n\n  dep_alias = whitespace \"as\" whitespace (identifier as alias)\n  dependency_decl = \"dependency\" whitespace (quoted_string as target) [(dep_alias)]\n\n  # -- item expressions ---------------------------------------------------\n\n  zw_primitive = ((\"boundary\") / (\"line_start\") / (\"line_end\") / (\"word_boundary\") / (\"space\") / (\"non_boundary\")) as primitive\n  fn_lit = ((\"upcase\") / (\"downcase\") / (\"title_case\") / (\"reverse\") / (\"strip\") / (\"swapcase\")) as function\n  any_char_lit = (\"any_character\") as any_char\n  none_lit = (\"none\") as none\n\n  digit_cap = digit as digit\n  capture_reference_body = \"ref\" \"(\" [ws] digit_cap [ws] \")\"\n  capture_reference = capture_reference_body as ref\n\n  item_ref = identifier \".\" (identifier as qualified_name)\n  alias_reference = (!(keyword) identifier [(\".\" (identifier as qualified_name))] !\"{\" ) as alias\n\n  item_seq = item_atom\n  item_sep = ([ws] \"+\" [ws]) / whitespace\n  item_cont = &item_atom\n\n  range_arg = (quoted_string as lo) [ws] \"..\" [ws] (quoted_string as hi)\n  list_item = item\n  list_items = (list_item *((comma_ws / whitespace) list_item))\n  set_arg = ((quoted_string as single)) / (\"[\" [ws] ((list_item *((comma_ws / whitespace) list_item)) as list) [ws] \"]\")\n  alias_arg = (!zw_primitive !(keyword) identifier) as alias_ref\n  any_arg = range_arg / set_arg / alias_arg\n  any_ctor = \"any\" \"(\" [ws] (any_arg as any) [ws] \")\"\n  capture_ctor = \"capture\" \"(\" [ws] (item as capture_inner) [ws] \")\"\n  maybe_ctor = \"maybe\" \"(\" [ws] (item as maybe_inner) [ws] \")\"\n  some_ctor = \"some\" \"(\" [ws] (item as some_inner) [ws] \")\"\n\n  item_atom_start = \"\\\"\" / \"'\" / ident_first\n  cont_stop = \"to\" / \"before\" / \"after\" / \"not_before\" / \"not_after\" / \"}\"\n  alias_decl_stop = identifier [ws] \"=\"\n  item_atom = quoted_string / none_lit / zw_primitive / any_char_lit / any_ctor / capture_ctor / maybe_ctor / some_ctor / fn_lit / capture_reference / alias_reference\n  item = (item_atom 0*(item_sep !cont_stop !(alias_decl_stop) &item_atom_start item_atom)) as concatenation\n\n  # -- rules and stages ---------------------------------------------------\n\n  constraint_after = \"after\" whitespace (item as after)\n  constraint_before = \"before\" whitespace (item as before)\n  constraint_not_before = \"not_before\" whitespace (item as not_before)\n  constraint_not_after = \"not_after\" whitespace (item as not_after)\n  constraint = constraint_after / constraint_before / constraint_not_before / constraint_not_after\n  constraints = *(whitespace constraint)\n\n  compact_rule = \"sub\" whitespace (item_atom as from) whitespace (item_atom as to) ((*(whitespace constraint)) as constraints) [(when_guard)]\n\n  block_rule = \"sub\" [ws] \"{\" [ws] \"from\" whitespace (item as from) [ws] \"to\" whitespace (item as to) ((*(whitespace constraint)) as constraints) [(when_guard)] [ws] \"}\"\n\n  when_lang = (!(keyword) identifier) as when_lang\n  when_guard = (whitespace \"when\" whitespace (when_lang) *(((comma_ws / whitespace) (when_lang)))) as when\n\n  rule = block_rule / compact_rule\n\n  comment_item = ((\"#\" *(!%x0A chr)) as comment) / ((!(keyword) identifier) as noop)\n  # ISC-WF-1 \u00a73.2: a `use` directive is a rule-line item \u2014 items inside a\n  # parallel/sequence block participate in that block's single pass, and\n  # the expansion flattens the referenced ruleset's rules at this\n  # position (mirrors interscript-rs grammar/isc.parg rule_line).\n  rule_line = [ws] (rule / use_directive / comment_item) [ws]\n  rule_items = *(rule_line)\n  sequence_block = \"sequence\" [ws] \"{\" [ws] (rule_items as sequence) [ws] \"}\"\n  parallel_block = \"parallel\" [ws] \"{\" [ws] (rule_items as parallel) [ws] \"}\"\n\n  separator_part = whitespace \"separator\" whitespace (item_atom as separator)\n  separate_directive = (\"separate\") as separate [(separator_part)]\n  case_directive = ((\"downcase\") / (\"upcase\")) as case\n  case_kwargs_part = whitespace (kwarg_list as case_kwargs)\n  title_case_directive = (\"title_case\") as case [(case_kwargs_part)]\n  string_case_directive = case_directive / title_case_directive\n  compose_directive = ((\"compose\") / (\"decompose\")) as compose\n  kwarg = (identifier as kwarg_name) [ws] \":\" [ws] ((quoted_string) as kwarg_value)\n  kwarg_item = (kwarg) as kwarg\n  kwarg_list = (kwarg_item *(comma_ws kwarg_item))\n  funcall_kwargs_part = whitespace (kwarg_list as funcall_kwargs)\n  rababa_directive = (\"rababa\") as funcall_name [(funcall_kwargs_part)]\n  run_dep = \"map.\" (identifier as dep) \".stage.\" (identifier as stage)\n  run_stage_only = (\"stage.\" (identifier as stage)) as run_stage_only\n  run_rule = \"run\" whitespace ((run_dep) / run_stage_only)\n\n  bare_rule = (rule) as bare_rule\n\n  use_alias = (identifier) as use_alias\n  use_qualified = \".\" (identifier as qualified_name)\n  use_overrides_part = whitespace \"override\" [ws] \"{\" [ws] ((*(rule_line)) as use_overrides) [ws] \"}\"\n  use_directive = ((\"use\" whitespace (use_alias) [(use_qualified)] [(use_overrides_part)]) as use)\n\n  stage_item = [ws] (sequence_block / parallel_block / run_rule / separate_directive / string_case_directive / compose_directive / rababa_directive / use_directive / bare_rule / comment_item) [ws]\n  stage_items = *(stage_item)\n  stage_name_paren = \"(\" (identifier as stage_name) \")\"\n  stage_name_ws = whitespace (identifier as stage_name)\n  stage_block = \"stage\" (stage_name_paren / stage_name_ws) [ws] \"{\" [ws] (stage_items as stage) [ws] \"}\"\n\n  ruleset_name_ws = whitespace (identifier as ruleset_name)\n  ruleset_block = \"ruleset\" (ruleset_name_ws) [ws] \"{\" [ws] (stage_items as ruleset) [ws] \"}\"\n\n  # -- tests ---------------------------------------------------------------\n\n  test_note = whitespace \"note\" whitespace (quoted_string as note)\n  test_line = [whitespace] (quoted_string as input) arrow (quoted_string as expected) [(test_note)] [whitespace]\n  test_items = *(test_line)\n  tests_block = \"tests\" [whitespace] \"{\" [ws] (test_items as tests) [ws] \"}\"\n\n  # -- system --------------------------------------------------------------\n\n  language_ident = (!(keyword) identifier) as language\n  languages_decl = (\"languages\" whitespace ((language_ident *(((comma_ws / whitespace) (language_ident))))) as languages)\n\n  block_item = [whitespace] (metadata_block / aliases_block / tests_block / languages_decl / ruleset_block / stage_block / dependency_decl) [whitespace]\n  body_items = *(block_item)\n  system_block = \"system\" whitespace ((quoted_string) as system_code) [whitespace] \"{\" [ws] ((*(block_item)) as body) [ws] \"}\" [whitespace]\n  isc_source = [whitespace] ((system_block) as system) [whitespace]\n\n  entry isc: isc_source\n}\n"
